from abc import ABC, abstractmethod

class Employee(ABC):
    def __init__(self, name):
        self.name = name

    @abstractmethod
    def calculateSalary(self):
        pass

class FullTimeEmployee(Employee):
    def __init__(self, name, monthly_salary):
        super().__init__(name)
        self.monthly_salary = monthly_salary

    def calculateSalary(self):
        return self.monthly_salary

class PartTimeEmployee(Employee):
    def __init__(self, name, hourly_rate, hours):
        super().__init__(name)
        self.hourly_rate = hourly_rate
        self.hours = hours

    def calculateSalary(self):
        return self.hourly_rate * self.hours

def main():
    import sys
    lines = [line.strip() for line in sys.stdin.readlines()]

    if not lines:
        return

    employee_type = lines[0].strip()

    if employee_type == "fulltime":
        if len(lines) < 2:
            print(-1)
            return
        try:
            monthly_salary = int(lines[1])
        except ValueError:
            print(-1)
            return
        emp = FullTimeEmployee("Employee", monthly_salary)
        print(emp.calculateSalary())

    elif employee_type == "parttime":
        if len(lines) < 2:
            print(-1)
            return
        parts = lines[1].split()
        if len(parts) < 2:
            print(-1)
            return
        try:
            hourly_rate = int(parts[0])
            hours = int(parts[1])
        except ValueError:
            print(-1)
            return
        emp = PartTimeEmployee("Employee", hourly_rate, hours)
        print(emp.calculateSalary())

    else:
        print(-1)

if __name__ == "__main__":
    main()
